s em +2 de poder e Ares em +3 de poder.","O bônus vale para os dois jogadores enquanto este terreno ocupa o espaço compartilhado."],"sourceCard":"codex-clipboard-44c87658-0390-4813-b67e-ca0b19864760.png","specialOnly":false},{"id":"labirinto-dedalos","name":"Labirinto de Dédalos","power":0,"faction":"Grécia","tags":[],"type":"Terreno","symbol":"⌁","cost":null,"kind":"terrain","glow":"rgba(36,91,137,.42)","badgeKey":"greece","art":"assets/terrains/labirinto-dedalos.png","abilityTitle":"Bônus de Terreno","ability":"Fortalece o Minotauro e os monstros gregos em +2 de poder.","previewOnly":false,"story":["Labirinto de Dédalos · Terreno · Facção Grécia.","Fortalece o Minotauro e os monstros gregos em +2 de poder.","O bônus vale para os dois jogadores enquanto este terreno ocupa o espaço compartilhado."],"sourceCard":"codex-clipboard-0a0b4557-0561-400b-9d7f-d3022d4e15a7.png","specialOnly":false},{"id":"nilfheim","name":"Nilfheim","power":0,"faction":"Nórdicos","tags":[],"type":"Terreno","symbol":"⌁","cost":null,"kind":"terrain","glow":"rgba(134,91,178,.42)","badgeKey":"norse","art":"assets/terrains/nilfheim.png","abilityTitle":"Bônus de Terreno","ability":"Fortalece Loki e os gigantes de gelo em +2 de poder.","previewOnly":false,"story":["Nilfheim · Terreno · Facção Nórdicos.","Fortalece Loki e os gigantes de gelo em +2 de poder.","O bônus vale para os dois jogadores enquanto este terreno ocupa o espaço compartilhado."],"sourceCard":"codex-clipboard-722d05ed-a942-4260-8793-ede44b99ff93.png","specialOnly":false},{"id":"asgard","name":"Asgard","type":"Local","kind":"location","faction":"Nórdicos","symbol":"⌂","power":0,"cost":null,"badgeKey":"norse","glow":"rgba(134,111,190,.42)","art":"assets/locations/asgard.png","abilityTitle":"Bônus de Local","ability":"Enquanto este Local estiver ativo, todos os nórdicos recebem +2 de poder, nos dois lados do campo.","previewOnly":false,"story":["Asgard · Local.","Enquanto este Local estiver ativo, todos os nórdicos recebem +2 de poder, nos dois lados do campo.","O bônus se soma ao Terreno ativo e termina ao encerrar o Round."],"specialOnly":false,"tags":[]},{"id":"egito","name":"Egito","type":"Local","kind":"location","faction":"Egípcios","symbol":"⌂","power":0,"cost":null,"badgeKey":"egypt","glow":"rgba(134,111,190,.42)","art":"assets/locations/egito.png","abilityTitle":"Bônus de Local","ability":"Enquanto este Local estiver ativo, todos os egípcios recebem +2 de poder, nos dois lados do campo.","previewOnly":false,"story":["Egito · Local.","Enquanto este Local estiver ativo, todos os egípcios recebem +2 de poder, nos dois lados do campo.","O bônus se soma ao Terreno ativo e termina ao encerrar o Round."],"specialOnly":false,"tags":[]},{"id":"olho-que-tudo-ve","name":"Olho que Tudo Vê","type":"Equipamento","kind":"equipment","faction":"Egípcios","badgeKey":"egypt","power":0,"cost":null,"symbol":"⚔","glow":"rgba(195,168,89,.42)","abilityTitle":"Equipar","ability":"Hórus, Rá e Osíris recebem +4 de poder. Loki copiando uma dessas identidades também pode equipar. Apenas um por portador.","art":"assets/equipment/olho-que-tudo-ve.png","previewOnly":false,"story":["Olho que Tudo Vê · Equipamento.","Somente Hórus, Rá e Osíris podem equipar. Concede +4 de poder.","Escolha um personagem aliado compatível em campo."],"specialOnly":false,"tags":[]},{"id":"raio-de-zeus","name":"Raio de Zeus","type":"Equipamento","kind":"equipment","faction":"Grécia","badgeKey":"greece","power":0,"cost":null,"symbol":"⚔","glow":"rgba(195,168,89,.42)","abilityTitle":"Equipar","ability":"Somente Zeus pode equipar. Concede +4 de poder. Apenas um Raio por portador.","art":"assets/equipment/raio-de-zeus.png","previewOnly":false,"story":["Raio de Zeus · Equipamento.","Somente Zeus pode equipar. Concede +4 de poder.","Escolha um personagem aliado compatível em campo."],"specialOnly":false,"tags":[]},{"id":"excalibur","name":"Excalibur","type":"Equipamento","kind":"equipment","faction":"Universal","badgeKey":"celtic","power":0,"cost":null,"symbol":"⚔","glow":"rgba(195,168,89,.42)","abilityTitle":"Equipar","ability":"Apenas uma Excalibur por portador. Rei Arthur recebe +4. Lukyan se transforma em Rei de Todos e mantém seus buffs, sem +4 extra.","art":"assets/equipment/excalibur.png","previewOnly":false,"story":["Excalibur · Equipamento.","Somente Rei Arthur e Lukyan base podem equipar. Rei Arthur recebe +4 de poder. Lukyan base se transforma em Lukyan — Rei de Todos, uma carta especial que não entra no baralho nem na mão.","Escolha um personagem aliado compatível em campo."],"specialOnly":false,"tags":[]},{"id":"eclipse-lunar","name":"Eclipse Lunar","type":"Clima","kind":"event","faction":"Universal","symbol":"◉","power":0,"cost":null,"glow":"rgba(199,65,65,.5)","art":"assets/eclipse/eclipse-lunar.png","abilityTitle":"Destino Celestial","ability":"Mulher e Homem da facção Monstros assumem as formas Alfa e Beta. Lobisomens transformados pelo Solar recuperam sua forma original. Dobra o poder dos lobisomens, vampiros e de Ártemis; Apolo e Rá perdem metade, arredondada para baixo.","previewOnly":false,"specialOnly":true,"story":["Eclipse Lunar · Clima/Evento.","Dobra o poder dos lobisomens, vampiros e de Ártemis. Apolo e Rá perdem metade do poder, arredondada para baixo.","O efeito vale para as cartas já em campo e para as que entrarem depois, nos dois lados. Local e Terreno continuam ativos.","Esta é uma forma sorteada do Eclipse e não pode entrar no baralho ou na mão."],"tags":[]},{"id":"eclipse-solar","name":"Eclipse Solar","type":"Clima","kind":"event","faction":"Universal","symbol":"◉","power":0,"cost":null,"glow":"rgba(242,158,63,.5)","art":"assets/eclipse/eclipse-solar.png","abilityTitle":"Destino Celestial","ability":"Dobra o poder de Apolo e Rá. Vampiros vão ao Submundo; lobisomens Beta e Omega viram Homem, e Alfa vira Mulher. Ártemis perde metade do poder, arredondada para baixo.","previewOnly":false,"specialOnly":true,"story":["Eclipse Solar · Clima/Evento.","Dobra o poder de Apolo e Rá. Vampiros vão ao Submundo; lobisomens Beta e Omega viram Homem, e Alfa vira Mulher. Ártemis perde metade do poder, arredondada para baixo.","O efeito vale para as cartas já em campo e para as que entrarem depois, nos dois lados. Local e Terreno continuam ativos.","Esta é uma forma sorteada do Eclipse e não pode entrar no baralho ou na mão."],"tags":[]},{"id":"loki","name":"Loki","power":3,"faction":"Nórdicos","type":"Personagem","subtype":"Deus","kind":"unit","symbol":"ᚠ","glow":"rgba(134,91,178,.42)","badgeKey":"norse","art":"assets/cards-20261017/loki.png","abilityTitle":"Ilusão Traiçoeira","ability":"Ao entrar, copia a habilidade, a identidade e o poder completo de um inimigo, incluindo bônus e equipamentos. A cópia termina ao sair do campo ou encerrar o Round.","previewOnly":false,"abilityPending":false,"story":["Loki · Deus · Facção Nórdicos.","Habilidade — Ilusão Traiçoeira: Ao entrar, copia a habilidade, a identidade e o poder completo de um inimigo, incluindo bônus e equipamentos. A cópia termina ao sair do campo ou encerrar o Round."],"sourceCard":"codex-clipboard-1ba6e065-64f9-4362-b9d1-2c67da30a35c.png","hologram":"assets/holograms/loki-hologram.png","specialOnly":false,"tags":[],"cost":null}],"entries":{"loki":["copy"],"hades":["revive"],"isis":["revive_cost"],"anubis":["anubis"],"afrodite":["steal"],"hermes":["move"],"ragnar":["rally"],"seth":["shuffle_lane"],"thor":["destroy_strongest"],"zeus":["destroy_two"],"artemis":["hunt_monsters"],"medusa":["petrify"],"poseidon":["tsunami"],"odin":["schedule_foresight"],"horus":["reveal"],"butter":["steal_hand"],"osiris":[],"dionisio":["silence"],"apolo":["double_lane"],"ares":["war_buff"],"hefesto":["improve"],"lukyan":["crowd_bonus"],"minotauro":["alone_bonus"],"sobek":["ally_bonus"],"aquiles":["greek_bonus"],"beowulf":["monster_bonus"],"lobo-beta":["summon_betas"]},"terrain":{"yggdrasil":[{"ids":["odin"],"bonus":2}],"alto-egito":[{"faction":"Egípcios","bonus":2}],"baixo-egito":[{"faction":"Egípcios","bonus":2}],"bifrost":[{"faction":"Nórdicos","excludeIds":["loki"],"bonus":2}],"esparta":[{"ids":["ares"],"bonus":3},{"tagsAny":["espartano"],"bonus":2}],"labirinto-dedalos":[{"ids":["minotauro"],"bonus":2},{"faction":"Grécia","tagsAny":["monstro"],"bonus":2}],"campo-troia":[{"ids":["aquiles","athena","ares"],"bonus":3}],"nilfheim":[{"ids":["loki"],"bonus":2},{"tagsAny":["gigante-de-gelo"],"bonus":2}]},"equipment":{"mjolnir":{"ids":["thor"],"bonus":4},"olho-que-tudo-ve":{"ids":["horus","ra","osiris"],"bonus":4},"raio-de-zeus":{"ids":["zeus"],"bonus":4},"runas-nordicas":{"faction":"Nórdicos","bonus":2},"excalibur":{"ids":["rei-arthur","lukyan"],"bonus":4,"transformId":"lukyan","transformTo":"lukyan-rei-de-todos"}},"locations":{"asgard":"Nórdicos","egito":"Egípcios","grecia":"Grécia"},"special":["lukyan-rei-de-todos","eclipse-lunar","eclipse-solar"],"titles":{"revive":"Hades: escolha uma unidade do seu Submundo","revive_cost":"Ísis: ressuscitar carta de até 2 de poder","anubis":"Anúbis: escolha uma unidade inimiga","anubis_revive":"Anúbis: recuperar carta de mesmo poder","steal":"Afrodite: escolha um inimigo com menos de 5 de poder","copy":"Loki: escolha qual inimigo copiar","move":"Hermes: escolha outro aliado","move_lane":"Hermes: escolha a nova fileira","rally":"Ragnar: reunir o aliado de menor poder","shuffle_lane":"Seth: escolha a fileira","improve":"Hefestos: escolha um aliado equipado","equip":"Escolha quem receberá o equipamento","foresight":"Odin: observar o topo do baralho","destroy_strongest":"Thor: escolha o inimigo de maior poder"}}$rules$::jsonb $$;


create or replace function public._r_live(s jsonb) returns boolean language sql immutable set search_path='' as $$
 select case when s ? 'silenceTurns' then coalesce((s->>'silenceTurns')::integer,0)<=0 else coalesce((s->>'round')::integer,1)>coalesce((s->>'silenceUntilRound')::integer,0) end $$;
create or replace function public._r_identity(u jsonb) returns text language sql immutable set search_path='' as $$ select coalesce(u->>'copiedFrom',u->>'cardId') $$;
create or replace function public._r_shield(s jsonb,t text,l integer) returns boolean language sql stable set search_path='' as $$
 select (public._r_live(s) or coalesce(s->>'silenceTeam'=public._r_other(t),false)) and exists(select 1 from jsonb_array_elements(coalesce(s#>array[t,'field'],'[]'::jsonb)) v where coalesce((v->>'lane')::integer,0)=l and public._r_id(v)='heimdall') $$;
create or replace function public._r_protect(s jsonb,t text,l integer,src text) returns boolean language sql stable set search_path='' as $$ select src<>t and public._r_shield(s,t,l) $$;
create or replace function public._r_active(s jsonb,t text,u jsonb) returns boolean language sql stable set search_path='' as $$
 select public._r_live(s) or coalesce(s->>'silenceTeam'=public._r_other(t) and public._r_shield(s,t,coalesce((u->>'lane')::integer,0)),false) $$;
create or replace function public._r_enabled(x jsonb,e jsonb) returns boolean language sql stable set search_path='' as $$
 select case when public._r_unit(x->'s',e->>'team',e->>'uid') is not null then public._r_active(x->'s',e->>'team',public._r_unit(x->'s',e->>'team',e->>'uid'))
 else public._r_live(x->'s') or coalesce((e->>'shielded')::boolean,false) and public._r_shield(x->'s',e->>'team',coalesce((e->>'lane')::integer,0))
 or e->>'op'='equip' and exists(select 1 from jsonb_array_elements(x#>array['s',e->>'team','field']) v where public._r_active(x->'s',e->>'team',v)) end $$;
create or replace function public._r_grave_power(g jsonb) returns numeric language sql stable set search_path='' as $$ select coalesce((g->>'deathPower')::numeric,(public._r_card(g->>'cardId')->>'power')::numeric,0) $$;
create or replace function public._r_gear_compatible(id text,u jsonb) returns boolean language sql stable set search_path='' as $$
 select coalesce(case when (public._r_data()#>array['equipment',id]) ? 'ids' then (public._r_data()#>array['equipment',id,'ids']) ? public._r_identity(u) else public._r_data()#>>array['equipment',id,'faction']=public._r_card(public._r_identity(u))->>'faction' end,false) $$;
create or replace function public._r_equip(id text,u jsonb) returns boolean language sql stable set search_path='' as $$
 select public._r_gear_compatible(id,u) and not ((coalesce(u->'equipment','[]'::jsonb)||coalesce(u->'copiedEquipment','[]'::jsonb)) ? id) $$;


create or replace function public._r_power(s jsonb,t text,u jsonb,depth integer default 0)
returns numeric language plpgsql stable set search_path='' as $$
declare c jsonb:=public._r_card(public._r_identity(u)); a jsonb:=s->t; id text:=public._r_id(u); p numeric:=coalesce((c->>'power')::numeric,0); n integer; item jsonb; gear text; r jsonb; climate text:=s#>>'{sharedZones,climate}'; enemy numeric;
begin
 if not public._r_active(s,t,u) then return coalesce((public._r_card(u->>'cardId')->>'power')::numeric,0);end if;
 p:=coalesce((u->>'copiedBasePower')::numeric,p)+coalesce((u->>'bonus')::numeric,0);
 if id='lukyan' and exists(select 1 from jsonb_array_elements(a->'field') v where v->>'uid'<>u->>'uid' and v->>'lane'=u->>'lane') then p:=p+3;end if;
 if id='hercules' then p:=p+least(12,coalesce((u->>'progress')::integer,0));end if;
 for gear in select jsonb_array_elements_text(coalesce(u->'equipment','[]'::jsonb)||coalesce(u->'copiedEquipment','[]'::jsonb)) loop if public._r_gear_compatible(gear,u) then p:=p+coalesce((public._r_data()#>>array['equipment',gear,'bonus'])::integer,0);end if;end loop;
 if id in ('soldado-esparta','guardiao-nordico') then select count(*)::integer into n from jsonb_array_elements(a->'field') v where public._r_identity(v)=id and v->>'uid'<>u->>'uid' and v->>'lane'=u->>'lane';p:=p*power(2::numeric,n);end if;
 if id='lobo-alfa' then p:=p+2*(select count(*) from jsonb_array_elements(a->'field') v where public._r_identity(v)='lobo-beta' and v->>'lane'=u->>'lane');end if;
 p:=p+2*(select count(*) from jsonb_array_elements(a->'field') v where v->>'uid'<>u->>'uid' and public._r_id(v)='athena' and public._r_active(s,t,v) and (v->>'lane')::integer=(u->>'lane')::integer);
 if id='lobo-omega' and depth=0 and (select count(*) from jsonb_array_elements(a->'field') v where v->>'lane'=u->>'lane')=1 then
  select coalesce(sum(public._r_power(s,public._r_other(t),v,1)),0) into enemy from jsonb_array_elements(coalesce(s#>array[public._r_other(t),'field'],'[]'::jsonb)) v where v->>'lane'=u->>'lane';if enemy>p then p:=p+8;end if;
 end if;
 if id in ('mulher','homem') then select count(*)::integer into n from jsonb_array_elements(a->'field') v where public._r_identity(v)='homem' and v->>'lane'=u->>'lane' and (id='mulher' or v->>'uid'<>u->>'uid');p:=p*power(2::numeric,n);end if;
 p:=p*coalesce((u->>'multiplier')::numeric,1);
 p:=p*power(2::numeric,(select count(*) from jsonb_array_elements(a->'field') v where public._r_id(v)='apolo' and public._r_active(s,t,v) and v->>'lane'=u->>'lane'));
 if not public._r_protect(s,t,(u->>'lane')::integer,coalesce(s#>>'{zoneOwners,local}',t)) and public._r_data()#>>array['locations',s#>>'{sharedZones,local}']=c->>'faction' then p:=p+2;end if;
 if not public._r_protect(s,t,(u->>'lane')::integer,coalesce(s#>>'{zoneOwners,terrain}',t)) then p:=p+public._terrain_bonus(s#>>'{sharedZones,terrain}',public._r_identity(u));end if;
 if c->>'faction'='Grécia' then p:=p+coalesce((a->>'greekAura')::numeric,0);end if;if c->>'faction'='Nórdicos' then p:=p+coalesce((a->>'norseAura')::numeric,0);end if;
 if id='lukyan-rei-de-todos' then p:=p*power(2::numeric,greatest(0,jsonb_array_length(a->'field')-1));end if;
 if not public._r_protect(s,t,(u->>'lane')::integer,coalesce(s#>>'{zoneOwners,climate}',t)) then
  if climate='eclipse-lunar' then if public._r_identity(u) in ('lobo-alfa','lobo-beta','lobo-omega','artemis') or public._eclipse_is_vampire(public._r_identity(u)) then p:=p*2;end if;if public._r_identity(u) in ('apolo','ra') then p:=floor(p/2);end if;
  elsif climate='eclipse-solar' then if public._r_identity(u) in ('apolo','ra') then p:=p*2;end if;if public._r_identity(u)='artemis' then p:=floor(p/2);end if;end if;
 end if;
 p:=greatest(0,floor(p+coalesce((u->>'powerShift')::numeric,0)));
 p:=greatest(0,floor(p+coalesce((u->>'copyOffset')::numeric,0)+coalesce((u->>'reviveOffset')::numeric,0)));
 return p;
end; $$;

create or replace function public._r_grave_ok(x jsonb,e jsonb,g jsonb) returns boolean language plpgsql stable set search_path='' as $$
declare c jsonb:=public._r_card(g->>'cardId'); zone text;
begin
 if c='{}'::jsonb or coalesce((c->>'specialOnly')::boolean,false) or g->>'owner' is distinct from e->>'owner' then return false;end if;
 if e->>'op'='revive' and c->>'kind'<>'unit' then return false;end if;
 if e->>'op'='revive_cost' and coalesce((c->>'power')::numeric,0)>2 then return false;end if;
 if e->>'op'='anubis_revive' and (c->>'kind'<>'unit' or public._r_grave_power(g)<>(e->>'wantedPower')::numeric) then return false;end if;
 if c->>'kind'='unit' then return true;end if;
 if c->>'kind'='equipment' then return exists(select 1 from jsonb_array_elements(x#>array['s',e->>'team','field']) a where public._r_equip(g->>'cardId',a));end if;
 zone:=case c->>'kind' when 'location' then 'local' when 'terrain' then 'terrain' else 'climate' end;
 return public._zone_can_replace(c,public._r_card(x#>>array['s','sharedZones',zone]));
end; $$;

create or replace function public._r_options(x jsonb,e jsonb) returns jsonb language plpgsql stable set search_path='' as $$
declare op text:=e->>'op'; t text:=e->>'team'; enemy text:=public._r_other(t); result jsonb:='[]'::jsonb; candidate jsonb; source_team text; p numeric; extreme numeric; include_it boolean; i integer; cid text;
begin
 if op in ('revive','revive_cost','anubis_revive') then
  for candidate in select value from jsonb_array_elements(x#>array['s',t,'grave']) where public._r_grave_ok(x,e,value) loop cid:=candidate->>'cardId';result:=result||jsonb_build_array(public._r_option(candidate->>'uid',(public._r_card(cid)->>'name')||case when op='anubis_revive' then ' · '||public._r_grave_power(candidate)::text||' poder no Submundo' else '' end,cid));end loop;
  return result||jsonb_build_array(public._r_option('skip','Não ressuscitar'));
 end if;
 if op in ('move_lane','shuffle_lane') then for i in 0..2 loop if op='shuffle_lane' or i<>(e->>'fromLane')::integer then result:=result||jsonb_build_array(public._r_option(i::text,'Fileira '||(i+1)::text));end if;end loop;return result;end if;
 if op='foresight' then if jsonb_array_length(coalesce(x#>array['r',e->>'owner','deck'],'[]'::jsonb))=0 then return result;end if;return jsonb_build_array(public._r_option('discard','Descartar o topo e ganhar +2 na soma'),public._r_option('keep','Manter no topo'));end if;
 if op not in ('copy','steal','anubis','destroy_strongest','move','rally','improve','equip') then return null;end if;
 source_team:=case when op in ('copy','steal','anubis','destroy_strongest') then enemy else t end;
 if op='destroy_strongest' then select max(public._r_power(x->'s',source_team,value)) into extreme from jsonb_array_elements(x#>array['s',source_team,'field']) where not public._r_protect(x->'s',source_team,(value->>'lane')::integer,t);end if;
 if op='rally' then select min(public._r_power(x->'s',t,value)) into extreme from jsonb_array_elements(x#>array['s',t,'field']) where value->>'lane'<>e->>'lane';end if;
 for candidate in select value from jsonb_array_elements(x#>array['s',source_team,'field']) loop
  p:=public._r_power(x->'s',source_team,candidate);
  include_it:=case op when 'copy' then true when 'steal' then p<5 when 'anubis' then true when 'destroy_strongest' then p=extreme when 'move' then candidate->>'uid'<>e->>'uid' when 'rally' then candidate->>'lane'<>e->>'lane' and p=extreme when 'improve' then jsonb_array_length(coalesce(candidate->'equipment','[]'::jsonb))>0 when 'equip' then public._r_active(x->'s',t,candidate) and public._r_equip(e->>'cardId',candidate) else false end;
  if source_team<>t and public._r_protect(x->'s',source_team,(candidate->>'lane')::integer,t) then include_it:=false;end if;
  if include_it then cid:=candidate->>'cardId';result:=result||jsonb_build_array(public._r_option(candidate->>'uid',coalesce((public._r_card(cid)->>'name')||case when op='anubis_revive' then ' · '||public._r_grave_power(candidate)::text||' poder no Submundo' else '' end,cid)||' · '||p::text||' poder · Fileira '||(((candidate->>'lane')::integer+1)::text),cid));end if;
 end loop;
 if op in ('steal','move') then result:=result||jsonb_build_array(public._r_option('skip',case when op='steal' then 'Não roubar' else 'Não mover' end));end if;return result;
end; $$;

create or replace function public._r_resolve(x jsonb,e jsonb) returns jsonb language plpgsql volatile set search_path='' as $$
declare op text:=e->>'op'; t text:=e->>'team'; enemy text:=public._r_other(t); owner_id text:=e->>'owner'; selected text:=e->>'selection'; lane integer:=coalesce((e->>'lane')::integer,0); u jsonb:=public._r_unit(x->'s',t,e->>'uid'); target jsonb; v jsonb; g jsonb; cid text; team text; id text; command text; amount numeric; wanted numeric; ids jsonb; list jsonb; vals jsonb; row_item jsonb; n integer; i integer; j integer; res jsonb; chosen_owner text;
begin
 if not public._r_enabled(x,e) then return x;end if;
 if op not in ('osiris','equip','anubis_revive','move_lane') and u is null then return x;end if;
 if op in ('copy','steal','anubis','destroy_strongest') and selected<>'skip' then target:=public._r_unit(x->'s',enemy,selected);if target is null or public._r_protect(x->'s',enemy,(target->>'lane')::integer,t) then return x;end if;end if;
 case op
 when 'copy' then
  target:=public._r_unit(x->'s',enemy,selected);if target is null then return x;end if;
  wanted:=public._r_power(x->'s',enemy,target);
  u:=(u-'copyOffset'-'copiedPower')||jsonb_build_object('copiedBasePower',coalesce((target->>'copiedBasePower')::numeric,(public._r_card(public._r_identity(target))->>'power')::numeric,0),'bonus',coalesce((target->>'bonus')::numeric,0),'multiplier',coalesce((target->>'multiplier')::numeric,1),'progress',coalesce((target->>'progress')::integer,0),'powerShift',coalesce((target->>'powerShift')::numeric,0),'copiedEquipment',coalesce(target->'equipment','[]'::jsonb)||coalesce(target->'copiedEquipment','[]'::jsonb),'copiedAbilityId',public._r_id(target),'copiedFrom',public._r_identity(target));
  x:=public._r_set_unit(x,t,u->>'uid',u);u:=u||jsonb_build_object('copyOffset',wanted-public._r_power(x->'s',t,u),'copiedPower',wanted);x:=public._r_set_unit(x,t,u->>'uid',u);
  if public._r_id(u)<>'loki' then for command in select jsonb_array_elements_text(coalesce(public._r_data()#>array['entries',public._r_id(u)],'[]'::jsonb)) loop x:=public._r_evt(x,e-'selection'||jsonb_build_object('op',command));end loop;end if;
 when 'revive','revive_cost','anubis_revive' then
  if selected='skip' then return x;end if;
  select value into g from jsonb_array_elements(x#>array['s',t,'grave']) where value->>'uid'=selected limit 1;
  if g is null or not public._r_grave_ok(x,e,g) then raise exception 'Esta carta não pode ser ressuscitada.';end if;
  x:=jsonb_set(x,array['s',t,'grave'],coalesce((select jsonb_agg(value order by ordinality) from jsonb_array_elements(x#>array['s',t,'grave']) with ordinality a(value,ordinality) where value->>'uid'<>selected),'[]'::jsonb),true);x:=public._r_grave_sync(x,t);
  x:=public._r_spawn(x,g->>'cardId',t,owner_id,lane,coalesce((g->>'progress')::integer,0));
  if op='anubis_revive' then target:=x#>array['s',t,'field', (jsonb_array_length(x#>array['s',t,'field'])-1)::text];target:=target||jsonb_build_object('reviveOffset',(e->>'wantedPower')::numeric-public._r_power(x->'s',t,target));x:=public._r_set_unit(x,t,target->>'uid',target);end if;
 when 'steal' then
  if selected<>'skip' then x:=public._r_visual(x,'hearts',enemy,jsonb_build_array(selected));end if;
  if selected='skip' then return x;end if;target:=public._r_unit(x->'s',enemy,selected);if target is null or public._r_power(x->'s',enemy,target)>=5 then raise exception 'Alvo fora da regra de Afrodite.';end if;
  x:=jsonb_set(x,array['s',enemy,'field'],coalesce((select jsonb_agg(value order by ordinality) from jsonb_array_elements(x#>array['s',enemy,'field']) with ordinality a(value,ordinality) where value->>'uid'<>selected),'[]'::jsonb),true);
  target:=target||jsonb_build_object('playedBy',owner_id,'uid',pg_catalog.gen_random_uuid()::text);x:=jsonb_set(x,array['s',t,'field'],(x#>array['s',t,'field'])||jsonb_build_array(target),true);
 when 'anubis' then
  target:=public._r_unit(x->'s',enemy,selected);if target is null then return x;end if;wanted:=public._r_power(x->'s',enemy,target);x:=public._r_destroy(x,enemy,jsonb_build_array(selected));x:=public._r_evt(x,e-'selection'||jsonb_build_object('op','anubis_revive','wantedPower',wanted));
 when 'destroy_strongest' then x:=public._r_destroy(x,enemy,jsonb_build_array(selected));
 when 'destroy_two' then
  select coalesce(jsonb_agg(value->'uid'),'[]'::jsonb) into ids from (select value from jsonb_array_elements(x#>array['s',enemy,'field']) where not public._r_protect(x->'s',enemy,(value->>'lane')::integer,t) order by random() limit 2) a;x:=public._r_visual(x,'lightning',enemy,ids);x:=public._r_destroy(x,enemy,ids);
 when 'hunt_monsters' then
  foreach team in array array['player_one','player_two'] loop select coalesce(jsonb_agg(value->'uid'),'[]'::jsonb) into ids from (select value from jsonb_array_elements(x#>array['s',team,'field']) where (public._r_card(public._r_identity(value))->'tags') ? 'monstro' and not public._r_protect(x->'s',team,(value->>'lane')::integer,t) order by public._r_power(x->'s',team,value) desc limit 2) a;x:=public._r_visual(x,'arrows',team,ids);x:=public._r_destroy(x,team,ids);end loop;
 when 'petrify' then
  x:=public._r_visual(x,'petrify',enemy);
  for chosen_owner in select key from jsonb_each(x->'r') where value->>'team'=enemy loop x:=jsonb_set(x,array['r',chosen_owner,'skipNextTurn'],'true'::jsonb,true);end loop;
 when 'tsunami' then
  x:=public._r_visual(x,'water',enemy);
  for v in select value from jsonb_array_elements(x#>array['s',enemy,'field']) where coalesce((value->>'lane')::integer,0)=0 loop x:=public._r_change(x,enemy,v->>'uid',t,-2);end loop;
 when 'move' then
  if selected='skip' then return x;end if;target:=public._r_unit(x->'s',t,selected);if target is not null then x:=public._r_evt(x,jsonb_build_object('op','move_lane','team',t,'owner',owner_id,'lane',lane,'targetUid',selected,'fromLane',(target->>'lane')::integer,'shielded',public._r_shield(x->'s',t,lane)));end if;
 when 'move_lane' then target:=public._r_unit(x->'s',t,e->>'targetUid');if target is not null then x:=public._r_set_unit(x,t,target->>'uid',jsonb_set(target,'{lane}',to_jsonb(selected::integer),true));end if;
 when 'rally' then target:=public._r_unit(x->'s',t,selected);if target is not null then x:=public._r_set_unit(x,t,selected,jsonb_set(target,'{lane}',to_jsonb(lane),true));end if;
 when 'shuffle_lane' then
  list:='[]'::jsonb;foreach team in array array['player_one','player_two'] loop for v in select value from jsonb_array_elements(x#>array['s',team,'field']) where (value->>'lane')::integer=selected::integer loop if not public._r_protect(x->'s',team,selected::integer,t) then list:=list||jsonb_build_array(jsonb_build_object('team',team,'uid',v->>'uid','power',public._r_power(x->'s',team,v)));end if;end loop;end loop;
  select coalesce(jsonb_agg(value->'power' order by random()),'[]'::jsonb) into vals from jsonb_array_elements(list);i:=0;for row_item in select value from jsonb_array_elements(list) loop target:=public._r_unit(x->'s',row_item->>'team',row_item->>'uid');target:=jsonb_set(target,'{powerShift}',to_jsonb(coalesce((target->>'powerShift')::numeric,0)+(vals->>i)::numeric-(row_item->>'power')::numeric),true);x:=public._r_set_unit(x,row_item->>'team',row_item->>'uid',target);i:=i+1;end loop;
 when 'improve' then x:=public._r_change(x,t,selected,t,3);
 when 'equip' then
  target:=public._r_unit(x->'s',t,selected);if target is null or not public._r_equip(e->>'cardId',target) then raise exception 'Equipamento incompatível.';end if;target:=jsonb_set(target,'{equipment}',coalesce(target->'equipment','[]'::jsonb)||jsonb_build_array(e->>'cardId'),true);x:=public._r_set_unit(x,t,selected,target);
 when 'schedule_foresight' then x:=public._r_set_unit(x,t,u->>'uid',jsonb_set(u,'{odinReady}','true'::jsonb,true));
 when 'foresight' then
  res:=x#>array['r',owner_id];if selected='discard' and jsonb_array_length(res->'deck')>0 then cid:=res#>>'{deck,0}';res:=jsonb_set(res,'{deck}',(res->'deck')-0,true);x:=jsonb_set(x,array['r',owner_id],res,true);x:=jsonb_set(x,array['s',t,'grave'],(x#>array['s',t,'grave'])||jsonb_build_array(jsonb_build_object('uid',pg_catalog.gen_random_uuid()::text,'cardId',cid,'owner',owner_id,'progress',0)),true);x:=public._r_grave_sync(x,t);x:=jsonb_set(x,array['s',t,'roundScoreBonus'],to_jsonb(coalesce((x#>>array['s',t,'roundScoreBonus'])::numeric,0)+2),true);end if;
 when 'reveal','steal_hand' then
  list:='[]'::jsonb;for row_item in select jsonb_build_object('owner',key,'res',value) from jsonb_each(x->'r') where value->>'team'=enemy loop i:=0;for v in select value from jsonb_array_elements(coalesce(row_item#>'{res,hand}','[]'::jsonb)) loop list:=list||jsonb_build_array(jsonb_build_object('owner',row_item->>'owner','cardId',v#>>'{}','index',i));i:=i+1;end loop;end loop;
  if op='reveal' then select coalesce(jsonb_agg(value->'cardId'),'[]'::jsonb) into vals from (select value from jsonb_array_elements(list) order by random() limit 2) a;x:=jsonb_set(x,array['r',owner_id,'privateEffects'],jsonb_build_object('id',pg_catalog.gen_random_uuid()::text,'kind','reveal','cards',vals),true);
  else
   command:='hand';
   if jsonb_array_length(list)=0 then command:='deck';for row_item in select jsonb_build_object('owner',key,'res',value) from jsonb_each(x->'r') where value->>'team'=enemy loop i:=0;for v in select value from jsonb_array_elements(coalesce(row_item#>'{res,deck}','[]'::jsonb)) loop list:=list||jsonb_build_array(jsonb_build_object('owner',row_item->>'owner','cardId',v#>>'{}','index',i));i:=i+1;end loop;end loop;end if;
   if jsonb_array_length(list)>0 then target:=list->floor(random()*jsonb_array_length(list))::integer;x:=jsonb_set(x,array['r',target->>'owner',command],(x#>array['r',target->>'owner',command])-(target->>'index')::integer,true);x:=jsonb_set(x,array['r',owner_id,'hand'],(x#>array['r',owner_id,'hand'])||jsonb_build_array(target->>'cardId'),true);
   else select value into target from jsonb_array_elements(coalesce(x#>array['s',enemy,'grave'],'[]'::jsonb)) where not coalesce((public._r_card(value->>'cardId')->>'specialOnly')::boolean,false) order by random() limit 1;
    if target is not null then x:=jsonb_set(x,array['s',enemy,'grave'],coalesce((select jsonb_agg(value order by ordinality) from jsonb_array_elements(x#>array['s',enemy,'grave']) with ordinality where value->>'uid'<>target->>'uid'),'[]'::jsonb),true);x:=public._r_grave_sync(x,enemy);x:=jsonb_set(x,array['r',owner_id,'hand'],(x#>array['r',owner_id,'hand'])||jsonb_build_array(target->>'cardId'),true);end if;
   end if;
  end if;
 when 'silence' then
  x:=jsonb_set(x,'{s,silenceTurns}','3'::jsonb,true);x:=jsonb_set(x,'{s,silenceTeam}',to_jsonb(t),true);x:=jsonb_set(x,'{s,silenceStartedBy}',to_jsonb(owner_id||':'||coalesce(x#>>array['r',owner_id,'turnsTaken'],'0')),true);x:=jsonb_set(x,'{s,silenceUntilRound}','0'::jsonb,true);
  select coalesce(jsonb_agg(value order by ordinality),'[]'::jsonb) into ids from jsonb_array_elements(coalesce(x#>'{s,effectQueue}','[]'::jsonb)) with ordinality where public._r_enabled(x,value);x:=jsonb_set(x,'{s,effectQueue}',ids,true);
 when 'double_lane' then null;
 when 'war_buff' then for v in select value from jsonb_array_elements(x#>array['s',t,'field']) where (value->>'lane')::integer=lane loop g:=public._r_card(v->>'cardId');amount:=case when (g->'tags') ? 'espartano' or v->>'cardId'='leonidas' then 2 when g->>'faction'='Grécia' then 1 else 0 end;x:=public._r_change(x,t,v->>'uid',t,amount);end loop;
 when 'crowd_bonus' then null;
 when 'alone_bonus' then if (select count(*) from jsonb_array_elements(x#>array['s',t,'field']) a where (a->>'lane')::integer=lane)=1 then x:=public._r_change(x,t,u->>'uid',t,3);end if;
 when 'ally_bonus' then if exists(select 1 from jsonb_array_elements(x#>array['s',t,'field']) a where a->>'uid'<>u->>'uid' and (a->>'lane')::integer=lane) then x:=public._r_change(x,t,u->>'uid',t,2);end if;
 when 'greek_bonus' then select count(*) into n from jsonb_array_elements(x#>array['s',t,'field']) a where a->>'uid'<>u->>'uid' and (a->>'lane')::integer=lane and public._r_card(a->>'cardId')->>'faction'='Grécia' and (public._r_card(a->>'cardId')->'tags') ?| array['heroi','soldado','espartano'];x:=public._r_change(x,t,u->>'uid',t,n);
 when 'monster_bonus' then if exists(select 1 from jsonb_array_elements((x#>'{s,player_one,field}')||(x#>'{s,player_two,field}')) a where public._r_card(a->>'cardId')->>'faction'='Monstros') then x:=public._r_change(x,t,u->>'uid',t,3);end if;
 when 'summon_betas' then
  res:=x#>array['r',owner_id];n:=(select count(*) from jsonb_array_elements_text(res->'hand') a where a='lobo-beta');select coalesce(jsonb_agg(value order by ordinality),'[]'::jsonb) into ids from jsonb_array_elements(res->'hand') with ordinality a(value,ordinality) where value<>'"lobo-beta"'::jsonb;x:=jsonb_set(x,array['r',owner_id,'hand'],ids,true);for i in 1..n loop x:=public._r_spawn(x,'lobo-beta',t,owner_id,lane);end loop;
 when 'osiris' then
  list:=x#>array['s',t,'field'];if jsonb_array_length(list)>0 then target:=list->floor(random()*jsonb_array_length(list))::integer;x:=public._r_change(x,t,target->>'uid',t,0,2);end if;
 else null;
 end case;
 return public._r_reconcile(x);
end; $$;

create or replace function public._r_drain(x jsonb,auto_choose boolean default false) returns jsonb language plpgsql volatile set search_path='' as $$
declare e jsonb; opts jsonb; pending jsonb; count_steps integer:=0;
begin
 while jsonb_array_length(x#>'{s,effectQueue}')>0 and x#>'{s,pendingEffect}' is null loop
  count_steps:=count_steps+1;if count_steps>256 then raise exception 'Sequência de habilidades longa demais.';end if;
  e:=x#>'{s,effectQueue,0}';x:=jsonb_set(x,'{s,effectQueue}',(x#>'{s,effectQueue}')-0,true);if not public._r_enabled(x,e) then continue;end if;
  opts:=public._r_options(x,e);
  if opts is not null and not(e ? 'selection') then
   if jsonb_array_length(opts)=0 then continue;end if;
   if auto_choose then e:=e||jsonb_build_object('selection',opts#>>'{0,value}');
   else pending:=jsonb_build_object('id',pg_catalog.gen_random_uuid()::text,'actor',e->>'owner','event',e,'options',opts,'title',coalesce(public._r_data()#>>array['titles',e->>'op'],'Escolha o alvo'));x:=jsonb_set(x,'{s,pendingEffect}',pending,true);exit;end if;
  end if;
  x:=public._r_resolve(x,e);
 end loop;return x;
end; $$;

create or replace function public._r_destroy(x jsonb,t text,ids jsonb,killed boolean default true) returns jsonb language plpgsql volatile set search_path='' as $$
declare u jsonb; grave jsonb:=coalesce(x#>array['s',t,'grave'],'[]'::jsonb); gear text; original text;
begin
 if killed and jsonb_array_length(ids)>0 then x:=public._r_visual(x,'destroy',t,ids);end if;
 for u in select value from jsonb_array_elements(coalesce(x#>array['s',t,'field'],'[]'::jsonb)) a(value) where ids ? (a.value->>'uid') loop
  original:=coalesce(u->>'eclipseOriginalCardId',u->>'sourceCardId',case when u->>'cardId'='lukyan-rei-de-todos' then 'lukyan' else u->>'cardId' end);
  grave:=grave||jsonb_build_array(jsonb_build_object('uid',pg_catalog.gen_random_uuid()::text,'cardId',original,'owner',u->>'playedBy','progress',coalesce((u->>'progress')::integer,0),'deathPower',public._r_power(x->'s',t,u)));
  for gear in select jsonb_array_elements_text(coalesce(u->'equipment','[]'::jsonb)) loop grave:=grave||jsonb_build_array(jsonb_build_object('uid',pg_catalog.gen_random_uuid()::text,'cardId',gear,'owner',u->>'playedBy','progress',0));end loop;
  if killed and public._r_active(x->'s',t,u) and public._r_id(u)='osiris' then x:=public._r_evt(x,jsonb_build_object('op','osiris','team',t,'owner',u->>'playedBy','lane',u->'lane','shielded',public._r_shield(x->'s',t,(u->>'lane')::integer)));end if;
 end loop;
 x:=jsonb_set(x,array['s',t,'grave'],grave,true);
 x:=jsonb_set(x,array['s',t,'field'],coalesce((select jsonb_agg(value order by ordinality) from jsonb_array_elements(x#>array['s',t,'field']) with ordinality a(value,ordinality) where not(ids ? (a.value->>'uid'))),'[]'::jsonb),true);
 return public._r_grave_sync(x,t);
end; $$;


do $patch$
declare d text;a text;b text;
begin
 d:=pg_get_functiondef('public._r_spawn(jsonb,text,text,text,integer,integer)'::regprocedure);
 d:=replace(d,'u is not null and public._r_live(x->''s'')','u is not null and public._r_active(x->''s'',t,u)');
 d:=replace(d,'if public._r_live(x->''s'') then','if public._r_live(x->''s'') or exists(select 1 from jsonb_array_elements(x#>array[''s'',t,''field'']) v where public._r_active(x->''s'',t,v)) then');
 -- Equipment has no source unit: a shielded allied unit may still receive it.
 d:=replace(d,'elsif c->>''kind''=''equipment'' then','elsif c->>''kind''=''equipment'' then');
 execute d;
 d:=pg_get_functiondef('public._r_reconcile(jsonb)'::regprocedure);
 a:='if enabled and u->>''cardId''=''lukyan''';b:='enabled:=public._r_active(x->''s'',t,u);if enabled and u->>''cardId''=''lukyan''';
 if position(b in d)=0 then if position(a in d)=0 then raise exception 'Reconciliação incompatível; aplique SQL 023 e 024.';end if;d:=replace(d,a,b);end if;d:=replace(d,'u:=u||jsonb_build_object(''sourceCardId'',''lukyan'',''cardId'',''lukyan-rei-de-todos'');','if exists(select 1 from jsonb_array_elements(x#>array[''s'',t,''field'']) v where v->>''uid''<>u->>''uid'' and v->>''lane''=u->>''lane'') then u:=u||jsonb_build_object(''bonus'',coalesce((u->>''bonus'')::numeric,0)+3);end if;u:=u||jsonb_build_object(''sourceCardId'',''lukyan'',''cardId'',''lukyan-rei-de-todos'');');execute d;
end $patch$;
create or replace function public._r_turn_end(s jsonb,actor text,t text,turn_no integer) returns jsonb language plpgsql volatile set search_path='' as $$
declare x jsonb:=jsonb_build_object('s',s,'r','{}'::jsonb);stamp text:=coalesce(s->>'round','1')||':'||turn_no::text;u jsonb;v jsonb;n integer;
begin
 if s#>>array['endedTurns',actor]=stamp then return s;end if;
 x:=jsonb_set(x,'{s,endedTurns}',coalesce(s->'endedTurns','{}'::jsonb)||jsonb_build_object(actor,stamp),true);
 for u in select value from jsonb_array_elements(coalesce(s#>array[t,'field'],'[]'::jsonb)) where value->>'playedBy'=actor loop
  if not public._r_active(x->'s',t,u) then continue;end if;
  if public._r_id(u)='ra' then for v in select value from jsonb_array_elements(x#>array['s',t,'field']) where value->>'lane'=u->>'lane' and public._r_card(public._r_identity(value))->>'faction'='Egípcios' loop x:=public._r_change(x,t,v->>'uid',t,1);end loop;end if;
  if public._r_id(u)='hercules' then v:=public._r_unit(x->'s',t,u->>'uid');v:=v||jsonb_build_object('progress',least(12,coalesce((v->>'progress')::integer,0)+1));x:=public._r_set_unit(x,t,u->>'uid',v);end if;
 end loop;
 n:=coalesce((s->>'silenceTurns')::integer,0);
 if n>0 and s->>'silenceStartedBy' is distinct from actor||':'||turn_no::text then x:=jsonb_set(x,'{s,silenceTurns}',to_jsonb(n-1),true);if n=1 then x:=jsonb_set(x,'{s}',(x->'s')-'silenceTeam',true);end if;end if;
 return public._r_reconcile(x)->'s';
end $$;
create or replace function public._r_round_end(s jsonb) returns jsonb language sql immutable set search_path='' as $$ select jsonb_set(s,'{endEffectsRound}',s->'round',true) $$;
do $cleanup$
declare d text;
begin
 d:=pg_get_functiondef('public._r_clear_round(jsonb)'::regprocedure);
 if position('rules_cleanup_v25' in d)=0 then d:=replace(d,'begin foreach',E'begin s:=(s-''silenceTeam''-''silenceStartedBy'')||''{"silenceTurns":0,"endedTurns":{}}''::jsonb;x:=jsonb_build_object(''s'',s,''r'',''{}''::jsonb); -- rules_cleanup_v25
 foreach');execute d;end if;
end $cleanup$;
-- Run after a fully resolved action, pass, or skipped turn; never between ability choices.
do $turn_hooks$
declare p record;d text;a text;b text;
begin
 for p in select f.oid,f.proname from pg_proc f join pg_namespace n on n.oid=f.pronamespace where n.nspname='public' and f.prokind='f' and f.proname in ('submit_duo_game_action','_submit_game_action_1v1','_audit_submit_game_action') loop
  d:=pg_get_functiondef(p.oid);if position('full_abilities_v1' in d)=0 or position('rules_turn_end_v25' in d)>0 then continue;end if;
  if p.proname='submit_duo_game_action' then
   a:='for next_user in select player_id from public.duo_match_players where match_id=g.id loop private_state:=';
   b:='s:=public._r_turn_end(s,actor::text,side_key,coalesce((all_players#>>array[actor::text,''turnsTaken''])::integer,0)); /* rules_turn_end_v25 */ '||a;
  else
   a:='if (coalesce((side->>''passed'')::boolean,false) or (jsonb_array_length(side->''hand'')=0 and jsonb_array_length(side->''deck'')=0))';
   b:='s:=public._r_turn_end(s,auth.uid()::text,side_key,coalesce((side->>''turnsTaken'')::integer,0));side:=s->side_key;other_side:=s->other_key; /* rules_turn_end_v25 */ '||a;
  end if;
  if position(a in d)=0 then raise exception 'Fim de turno desconhecido em %. Nenhuma alteração aplicada.',p.proname;end if;d:=replace(d,a,b);d:=replace(replace(d,'rodadas','Rounds'),'rodada','Round');d:=replace(d,'Rodada','Round');execute d;
 end loop;
end $turn_hooks$;


