do $permissions$
declare p record;
begin for p in select f.oid::regprocedure signature from pg_proc f join pg_namespace n on n.oid=f.pronamespace where n.nspname='public' and left(f.proname,3)='_r_' loop execute 'revoke all on function '||p.signature||' from public,anon,authenticated';end loop;end $permissions$;
notify pgrst,'reload schema';
commit;
